    '[[$corp_form]]' => '<style>
  .corp-form-section {
    position: relative;
    padding: 92px 0;
    color: #ffffff;
    background:
      radial-gradient(circle at 12% 10%, rgba(211, 117, 24, 0.24), transparent 34%),
      radial-gradient(circle at 88% 18%, rgba(255, 255, 255, 0.08), transparent 36%),
      linear-gradient(135deg, #313849 0%, #202633 100%);
    overflow: hidden;
  }

  .corp-form-section,
  .corp-form-section *,
  .corp-form-section *::before,
  .corp-form-section *::after {
    box-sizing: border-box;
    font-family: RobotoMono, Arial, sans-serif;
  }

  .corp-form-section__container {
    position: relative;
    z-index: 2;
    width: min(1180px, calc(100% - 40px));
    margin: 0 auto;
  }

  .corp-form-section__title {
    max-width: 920px;
    margin: 0 auto 18px;
    color: #ffffff;
    font-size: clamp(30px, 3.8vw, 52px);
    line-height: 1.12;
    font-weight: 700;
    text-align: center;
    letter-spacing: -0.04em;
  }

  .corp-form-section__subtitle {
    max-width: 800px;
    margin: 0 auto 42px;
    color: rgba(255, 255, 255, 0.76);
    font-size: 19px;
    line-height: 1.6;
    font-weight: 400;
    text-align: center;
  }

  .corp-lead-form {
    width: min(980px, 100%);
    margin: 0 auto;
    padding: 36px;
    border-radius: 32px;
    background: rgba(255, 255, 255, 0.11);
    border: 1px solid rgba(255, 255, 255, 0.16);
    box-shadow: 0 24px 60px rgba(0, 0, 0, 0.18);
    backdrop-filter: blur(16px);
  }

  .corp-lead-form__grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 16px;
  }

  .corp-lead-form__field {
    display: grid;
    gap: 8px;
  }

  .corp-lead-form__field--full {
    margin-top: 16px;
  }

  .corp-lead-form__field label {
    color: rgba(255, 255, 255, 0.9);
    font-size: 14px;
    line-height: 1.35;
    font-weight: 700;
  }

  .corp-lead-form__field input,
  .corp-lead-form__field textarea,
  .corp-lead-form__field select {
    width: 100%;
    min-height: 56px;
    padding: 0 18px;
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 18px;
    outline: none;
    background: #ffffff;
    color: #313849;
    font-size: 16px;
    line-height: 1.35;
    font-weight: 600;
    box-shadow: none;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
  }

  .corp-lead-form__field textarea {
    min-height: 150px;
    padding-top: 16px;
    padding-bottom: 16px;
    resize: vertical;
  }

  .corp-lead-form__field input::placeholder,
  .corp-lead-form__field textarea::placeholder {
    color: rgba(49, 56, 73, 0.48);
  }

  .corp-lead-form__field input:focus,
  .corp-lead-form__field textarea:focus,
  .corp-lead-form__field select:focus {
    border-color: #d37518;
    box-shadow: 0 0 0 4px rgba(211, 117, 24, 0.22);
  }

  .corp-lead-form__error-main,
  .corp-lead-form__success {
    width: min(980px, 100%);
    margin: 0 auto 18px;
    padding: 16px 18px;
    border-radius: 18px;
    color: #ffffff;
    border: 1px solid rgba(255, 255, 255, 0.18);
    font-size: 15px;
    line-height: 1.45;
    font-weight: 700;
  }

  .corp-lead-form__error-main {
    background: rgba(180, 36, 36, 0.9);
  }

  .corp-lead-form__success {
    background: rgba(39, 151, 112, 0.92);
  }

  .corp-lead-form__error {
    min-height: 18px;
    color: #ffb8a8;
    font-size: 12px;
    line-height: 1.35;
    font-weight: 600;
  }

  .corp-lead-form__captcha {
    margin-top: 20px;
    display: flex;
    justify-content: center;
  }

  .corp-lead-form__agree {
    margin-top: 22px;
    display: grid;
    grid-template-columns: 22px minmax(0, 1fr);
    gap: 12px;
    align-items: start;
    color: rgba(255, 255, 255, 0.76);
    font-size: 13px;
    line-height: 1.55;
    cursor: pointer;
  }

  .corp-lead-form__agree input {
    width: 18px;
    height: 18px;
    margin-top: 2px;
    accent-color: #d37518;
  }

  .corp-lead-form__agree a {
    color: #ffbd76;
    text-decoration: underline;
    text-underline-offset: 3px;
  }

  .corp-lead-form__agree a:hover {
    color: #ffffff;
  }

  .corp-lead-form__submit {
    width: 100%;
    min-height: 58px;
    margin-top: 24px;
    padding: 16px 24px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 0;
    border-radius: 999px;
    color: #ffffff;
    background: linear-gradient(135deg, #d37518, #f3a340);
    box-shadow: 0 16px 34px rgba(211, 117, 24, 0.32);
    font-size: 16px;
    line-height: 1.15;
    font-weight: 700;
    cursor: pointer;
    transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
  }

  .corp-lead-form__submit:hover {
    transform: translateY(-2px);
    background: linear-gradient(135deg, #b95f0d, #d37518);
    box-shadow: 0 20px 42px rgba(211, 117, 24, 0.38);
  }

  .corp-lead-form__submit:active {
    transform: translateY(0);
  }

  @media (max-width: 980px) {
    .corp-lead-form__grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  @media (max-width: 760px) {
    .corp-form-section {
      padding: 64px 0;
    }

    .corp-form-section__container {
      width: min(100% - 24px, 1180px);
    }

    .corp-form-section__title {
      font-size: 30px;
      line-height: 1.2;
    }

    .corp-form-section__subtitle {
      margin-bottom: 28px;
      font-size: 16px;
    }

    .corp-lead-form {
      padding: 24px;
      border-radius: 24px;
    }

    .corp-lead-form__grid {
      grid-template-columns: 1fr;
    }

    .corp-lead-form__field input,
    .corp-lead-form__field textarea,
    .corp-lead-form__field select {
      font-size: 15px;
    }

    .corp-lead-form__captcha {
      justify-content: flex-start;
      overflow-x: auto;
    }

    .corp-lead-form__agree {
      font-size: 12px;
    }
  }
</style>

<section class="corp-form-section" id="lead-form">
  <div class="corp-form-section__container">
    <h2 class="corp-form-section__title">
      Обсудим корпоративное обучение
    </h2>

    <p class="corp-form-section__subtitle">
      Оставьте заявку — мы свяжемся с вами, уточним задачи команды и предложим подходящий формат.
    </p>

    [[!FormIt?
      &hooks=`recaptchav2,spam,preHookFormLimitPerUser,CRMHook,telegramHook,Saveform`
      &csrfKey=`csrf_corp_ai`
      &validate=`name:required:minLength=3,phone:required,email:required:email,company:required,g-recaptcha-response:required,agreement:required,website:blank`
      &validationErrorMessage=`В форме содержатся ошибки!`
      &successMessage=`Сообщение успешно отправлено`
      &formName=`Corporate AI Lead (134)`
      &formEncrypt=`1`
      &emailFromName=`Центр программирования Progin.tech`
      &formFields=`name,phone,email,company,job_title,team_size,business_task,lead_type,page,agreement,utm_source,utm_medium,utm_campaign,utm_term,utm_content,website,form_load_time,mouse_clicks`
      &fieldNames=`name==Имя клиента,phone==Номер телефона,email==Email,company==Компания,job_title==Должность,team_size==Размер команды,business_task==Задача компании,lead_type==Тип заявки,page==Страница,agreement==Согласие на обработку данных,utm_source==Источник,utm_medium==Канал,utm_campaign==Кампания,utm_term==Ключевое слово,utm_content==Контент`
      &rcv3Action=`CorporateAILead`
    ]]

    [[!+fi.validation_error_message:notempty=`
      <div class="corp-lead-form__error-main">
        [[!+fi.validation_error_message]]
      </div>
    `]]

    [[!+fi.successMessage:notempty=`
      <div class="corp-lead-form__success">
        [[!+fi.successMessage]]
      </div>
    `]]

    <form action="korporativnye/#lead-form" method="POST" class="corp-lead-form" id="corpLeadForm" autocomplete="off">
      <input type="hidden" name="csrf_token" value="[[!csrfhelper_custom@cstm_csrf? &key=`csrf_corp_ai`]]">
      <input type="hidden" name="lead_type" value="corporate">
      <input type="hidden" name="page" value="/korporativnye:corporate-ai">

      <input type="hidden" name="utm_source" value="сайт">
      <input type="hidden" name="utm_medium" value="[[+utm_medium]]">
      <input type="hidden" name="utm_campaign" value="[[+utm_campaign]]">
      <input type="hidden" name="utm_term" value="[[+utm_term]]">
      <input type="hidden" name="utm_content" value="[[+utm_content]]">

      [[!+fi.error.csrf_token:notempty=`
        <div class="corp-lead-form__error-main">
          [[!+fi.error.csrf_token]]
        </div>
      `]]

      <div class="corp-lead-form__grid">
        <div class="corp-lead-form__field">
          <label for="corp-name">Ваше имя</label>
          <input
            type="text"
            id="corp-name"
            name="name"
            value="[[+fi.name]]"
            placeholder="Как к вам обращаться?"
            minlength="3"
            autocomplete="name"
            required
          >
          <span class="corp-lead-form__error" data-error="name">[[+fi.error.name]]</span>
        </div>

        <div class="corp-lead-form__field">
          <label for="corp-phone">Телефон</label>
          <input
            type="tel"
            id="corp-phone"
            name="phone"
            value="[[+fi.phone]]"
            placeholder="+7 (000) 000-00-00"
            inputmode="tel"
            autocomplete="tel"
            maxlength="18"
            required
          >
          <span class="corp-lead-form__error" data-error="phone">[[+fi.error.phone]]</span>
        </div>

        <div class="corp-lead-form__field">
          <label for="corp-email">Email</label>
          <input
            type="email"
            id="corp-email"
            name="email"
            value="[[+fi.email]]"
            placeholder="name@company.ru"
            autocomplete="email"
            required
          >
          <span class="corp-lead-form__error" data-error="email">[[+fi.error.email]]</span>
        </div>

        <div class="corp-lead-form__field">
          <label for="corp-company">Компания</label>
          <input
            type="text"
            id="corp-company"
            name="company"
            value="[[+fi.company]]"
            placeholder="Название компании"
            autocomplete="organization"
            required
          >
          <span class="corp-lead-form__error" data-error="company">[[+fi.error.company]]</span>
        </div>

        <div class="corp-lead-form__field">
          <label for="corp-job">Должность</label>
          <input
            type="text"
            id="corp-job"
            name="job_title"
            value="[[+fi.job_title]]"
            placeholder="Руководитель, HR, BI lead..."
            autocomplete="organization-title"
          >
          <span class="corp-lead-form__error" data-error="job_title">[[+fi.error.job_title]]</span>
        </div>

        <div class="corp-lead-form__field">
          <label for="corp-team">Размер команды</label>
          <input
            type="text"
            id="corp-team"
            name="team_size"
            value="[[+fi.team_size]]"
            placeholder="Например: 8 человек"
          >
          <span class="corp-lead-form__error" data-error="team_size">[[+fi.error.team_size]]</span>
        </div>
