<section class="corp-form-section" id="lead-form">
  <div class="corp-form-section__container">
    <h2 class="corp-form-section__title">
      Обсудим корпоративное обучение
    </h2>

    <p class="corp-form-section__subtitle">
      Оставьте заявку — мы свяжемся с вами, уточним задачи команды и предложим подходящий формат.
    </p>

    [[!FormIt?
      &hooks=`recaptchav2,spam,preHookFormLimitPerUser,CRMHook,telegramHook,Saveform`
      &csrfKey=`csrf_corp_ai`
      &validate=`name:required:minLength=3,phone:required,email:required:email,company:required,g-recaptcha-response:required,agreement:required,website:blank`
      &validationErrorMessage=`В форме содержатся ошибки!`
      &successMessage=`Сообщение успешно отправлено`
      &formName=`Corporate AI Lead ([[*id]])`
      &formEncrypt=`1`
      &emailFromName=`Центр программирования Progin.tech`
      &formFields=`name,phone,email,company,job_title,team_size,business_task,lead_type,page,agreement,utm_source,utm_medium,utm_campaign,utm_term,utm_content,website,form_load_time,mouse_clicks`
      &fieldNames=`name==Имя клиента,phone==Номер телефона,email==Email,company==Компания,job_title==Должность,team_size==Размер команды,business_task==Задача компании,lead_type==Тип заявки,page==Страница,agreement==Согласие на обработку данных,utm_source==Источник,utm_medium==Канал,utm_campaign==Кампания,utm_term==Ключевое слово,utm_content==Контент`
      &rcv3Action=`CorporateAILead`
    ]]

    [[!+fi.validation_error_message:notempty=`
      <div class="corp-lead-form__error-main">
        [[!+fi.validation_error_message]]
      </div>
    `]]

    [[!+fi.successMessage:notempty=`
      <div class="corp-lead-form__success">
        [[!+fi.successMessage]]
      </div>
    `]]

    <form action="[[~[[*id]]]]#lead-form" method="POST" class="corp-lead-form" id="corpLeadForm" autocomplete="off">
      <input type="hidden" name="csrf_token" value="[[!csrfhelper_custom@cstm_csrf? &key=`csrf_corp_ai`]]">
      <input type="hidden" name="lead_type" value="corporate">
      <input type="hidden" name="page" value="/[[*alias]]:corporate-ai">

      <input type="hidden" name="utm_source" value="[[+utm_source]]">
      <input type="hidden" name="utm_medium" value="[[+utm_medium]]">
      <input type="hidden" name="utm_campaign" value="[[+utm_campaign]]">
      <input type="hidden" name="utm_term" value="[[+utm_term]]">
      <input type="hidden" name="utm_content" value="[[+utm_content]]">

      [[!+fi.error.csrf_token:notempty=`
        <div class="corp-lead-form__error-main">
          [[!+fi.error.csrf_token]]
        </div>
      `]]

      <div class="corp-lead-form__grid">
        <div class="corp-lead-form__field">
          <label for="corp-name">Ваше имя</label>
          <input
            type="text"
            id="corp-name"
            name="name"
            value="[[+fi.name]]"
            placeholder="Как к вам обращаться?"
            minlength="3"
            autocomplete="name"
            required
          >
          <span class="corp-lead-form__error" data-error="name">[[+fi.error.name]]</span>
        </div>

        <div class="corp-lead-form__field">
          <label for="corp-phone">Телефон</label>
          <input
            type="tel"
            id="corp-phone"
            name="phone"
            value="[[+fi.phone]]"
            placeholder="+7 (000) 000-00-00"
            inputmode="tel"
            autocomplete="tel"
            maxlength="18"
            required
          >
          <span class="corp-lead-form__error" data-error="phone">[[+fi.error.phone]]</span>
        </div>

        <div class="corp-lead-form__field">
          <label for="corp-email">Email</label>
          <input
            type="email"
            id="corp-email"
            name="email"
            value="[[+fi.email]]"
            placeholder="name@company.ru"
            autocomplete="email"
            required
          >
          <span class="corp-lead-form__error" data-error="email">[[+fi.error.email]]</span>
        </div>

        <div class="corp-lead-form__field">
          <label for="corp-company">Компания</label>
          <input
            type="text"
            id="corp-company"
            name="company"
            value="[[+fi.company]]"
            placeholder="Название компании"
            autocomplete="organization"
            required
          >
          <span class="corp-lead-form__error" data-error="company">[[+fi.error.company]]</span>
        </div>

        <div class="corp-lead-form__field">
          <label for="corp-job">Должность</label>
          <input
            type="text"
            id="corp-job"
            name="job_title"
            value="[[+fi.job_title]]"
            placeholder="Руководитель, HR, BI lead..."
            autocomplete="organization-title"
          >
          <span class="corp-lead-form__error" data-error="job_title">[[+fi.error.job_title]]</span>
        </div>

        <div class="corp-lead-form__field">
          <label for="corp-team">Размер команды</label>
          <input
            type="text"
            id="corp-team"
            name="team_size"
            value="[[+fi.team_size]]"
            placeholder="Например: 8 человек"
          >
          <span class="corp-lead-form__error" data-error="team_size">[[+fi.error.team_size]]</span>
        </div>
      </div>

      <div class="corp-lead-form__field corp-lead-form__field--full">
        <label for="corp-task">Какая задача стоит перед командой?</label>
        <textarea
          id="corp-task"
          name="business_task"
          placeholder="Например: хотим ускорить подготовку отчётов, внедрить ИИ в BI/BA-процессы, обучить отдел маркетинга..."
        >[[+fi.business_task]]</textarea>
        <span class="corp-lead-form__error" data-error="business_task">[[+fi.error.business_task]]</span>
      </div>

      <div class="corp-lead-form__captcha">
        [[!recaptchav2_render]]
        [[!+fi.error.recaptchav2_error]]
      </div>

      [[!+fi.error.g-recaptcha-response:notempty=`
        <div class="corp-lead-form__error-main">
          [[!+fi.error.g-recaptcha-response]]
        </div>
      `]]

      <label class="corp-lead-form__agree">
        <input type="checkbox" name="agreement" value="1" [[+fi.agreement:eq=`1`:then=`checked`]] required>
        <span>
          Я принимаю
          <a href="/assets/files/soglasie-pd-ooo-proginskij-2026.pdf" target="_blank" rel="noopener noreferrer">пользовательское соглашение</a>
          и
          <a href="/assets/files/privacy-policy.pdf" target="_blank" rel="noopener noreferrer">политику обработки персональных данных</a>
        </span>
      </label>

      <span class="corp-lead-form__error" data-error="agreement">[[+fi.error.agreement]]</span>

      <button type="submit" class="corp-lead-form__submit">
        Получить предложение
      </button>

      <input
        type="text"
        name="website"
        value=""
        tabindex="-1"
        autocomplete="off"
        style="position:absolute;left:-9999px;top:-9999px;opacity:0;pointer-events:none;height:0;width:0;"
      >

      <input
        type="text"
        name="form_load_time"
        id="corp-form-load-time"
        value="[[+fi.form_load_time]]"
        tabindex="-1"
        autocomplete="off"
        style="position:absolute;left:-9999px;top:-9999px;opacity:0;pointer-events:none;height:0;width:0;"
      >

      <input
        type="text"
        name="mouse_clicks"
        id="corp-mouse-clicks"
        value="[[+fi.mouse_clicks]]"
        tabindex="-1"
        autocomplete="off"
        style="position:absolute;left:-9999px;top:-9999px;opacity:0;pointer-events:none;height:0;width:0;"
      >
    </form>
  </div>
</section>

<script>
  document.addEventListener(\'DOMContentLoaded\', function () {
    var form = document.getElementById(\'corpLeadForm\');
    var phone = document.getElementById(\'corp-phone\');
    var formLoadTime = document.getElementById(\'corp-form-load-time\');
    var mouseClicks = document.getElementById(\'corp-mouse-clicks\');

    if (!form || !phone) {
      return;
    }

    var startedAt = Date.now();
    var clickCount = 0;

    document.addEventListener(\'click\', function () {
      clickCount += 1;

      if (mouseClicks) {
        mouseClicks.value = String(clickCount);
      }
    });

    function updateFormLoadTime() {
      if (formLoadTime) {
        formLoadTime.value = String(((Date.now() - startedAt) / 1000).toFixed(2));
      }
    }

    setInterval(updateFormLoadTime, 1000);
    updateFormLoadTime();

    function onlyDigits(value) {
      return value.replace(/\\D/g, \'\');
    }

    function normalizeDigits(value) {
      var digits = onlyDigits(value);

      if (digits.startsWith(\'8\')) {
        digits = \'7\' + digits.slice(1);
      }

      if (digits.length === 10 && digits.startsWith(\'9\')) {
        digits = \'7\' + digits;
      }

      if (!digits.startsWith(\'7\')) {
        digits = \'7\' + digits;
      }

      return digits.slice(0, 11);
    }

    function formatPhone(value) {
      var digits = normalizeDigits(value);
      var result = \'+7\';

      if (digits.length > 1) {
        result += \' (\' + digits.slice(1, 4);
      }

      if (digits.length >= 4) {
        result += \') \' + digits.slice(4, 7);
      }

      if (digits.length >= 7) {
        result += \'-\' + digits.slice(7, 9);
      }

      if (digits.length >= 9) {
        result += \'-\' + digits.slice(9, 11);
      }

      return result;
    }

    function isValidPhone(value) {
      var digits = onlyDigits(value);

      if (!/^7\\d{10}$/.test(digits)) {
        return false;
      }

      var subscriber = digits.slice(1);

      if (/^(\\d)\\1{9}$/.test(subscriber)) {
        return false;
      }

      if (subscriber === \'0000000000\') {
        return false;
      }

      return true;
    }

    phone.addEventListener(\'focus\', function () {
      if (!phone.value.trim()) {
        phone.value = \'+7\';
      }
    });

    phone.addEventListener(\'input\', function () {
      phone.value = formatPhone(phone.value);

      if (onlyDigits(phone.value).length === 11 && isValidPhone(phone.value)) {
        phone.setCustomValidity(\'\');
      } else {
        phone.setCustomValidity(\'Введите корректный номер телефона\');
      }
    });

    phone.addEventListener(\'blur\', function () {
      if (onlyDigits(phone.value) === \'7\') {
        phone.value = \'\';
        phone.setCustomValidity(\'\');
      }
    });

    form.addEventListener(\'submit\', function (event) {
      updateFormLoadTime();

      if (mouseClicks) {
        mouseClicks.value = String(clickCount);
      }

      if (!isValidPhone(phone.value)) {
        event.preventDefault();

        var error = form.querySelector(\'[data-error="phone"]\');

        if (error) {
          error.textContent = \'Введите корректный номер телефона в формате +7 (999) 999-99-99\';
        }

        phone.setCustomValidity(\'Введите корректный номер телефона в формате +7 (999) 999-99-99\');
        phone.reportValidity();
        phone.focus();

        return false;
      }

      phone.setCustomValidity(\'\');
    });
  });
</script>',
