          'content' => '/**
 * FormIt
 *
 * A dynamic form processing Snippet for MODx Revolution.
 *
 * @var modX $modx
 * @var array $scriptProperties
 *
 * @package formit
 */
use Sterc\\FormIt;

$fi = new FormIt($modx, $scriptProperties);

$fi->initialize($modx->context->get(\'key\'));
$fi->loadRequest();

$fields = $fi->request->prepare();

return $fi->request->handle($fields);',
        ),
        'policies' => 
        array (
          'web' => 
          array (
          ),
        ),
        'source' => 
        array (
        ),
      ),
      'csrfhelper_custom' => 
      array (
        'fields' => 
        array (
          'id' => 76,
          'source' => 0,
          'property_preprocess' => false,
          'name' => 'csrfhelper_custom',
          'description' => 'Generates a CSRF token for a specific form.',
          'editor_type' => 0,
          'category' => 25,
          'cache_type' => 0,
          'snippet' => '$path = $modx->getOption(\'csrfhelper.core_path\', null, MODX_CORE_PATH . \'components/csrfhelper/\');
$path .= \'vendor/autoload.php\';
require_once $path;

use modmore\\CSRFHelper\\Csrf;
use modmore\\CSRFHelper\\Storage\\SessionStorage;

$key = $modx->getOption(\'key\', $scriptProperties, \'default\');

// Получаем значение параметра singleUseCsrf из настроек сниппета
$singleUse = $modx->getOption(\'singleUseCsrf\', $scriptProperties, 0);

$storage = new SessionStorage();
$csrf = new Csrf($storage, $modx->getUser());

try {
    if ($singleUse) {
        return $csrf->generate($key);
    }

    return $csrf->get($key);
}
catch (Error $e) {
    throw $e;
}
catch (Exception $e) {
    $modx->log(modX::LOG_LEVEL_ERROR, \'[csrfhelper] Could not safely generate the CSRF token: \' . $e->getMessage());
}
